func mcpPositiveInt(args map[string]any, key string, fallback int) (int, error) {
	value, ok := args[key]
	if !ok {
		return fallback, nil
	}
	switch typed := value.(type) {
	case float64:
		if typed >= 1 && typed <= float64(math.MaxInt) && math.Trunc(typed) == typed {
			return int(typed), nil
		}
	case int:
		if typed >= 1 {
