func execute(t *testing.T, cmd *cobra.Command, args ...string) (string, error) {
	t.Helper()

	var stdout bytes.Buffer
	cmd.SetOut(&stdout)
	cmd.SetErr(&stdout)
	cmd.SetArgs(args)
	err := cmd.Execute()
	return stdout.String(), err
}

func TestRootStatusShowsEntireEnvironment(t *testing.T) {
	configDir := t.TempDir()
	dataDir := t.TempDir()
	stateDir := t.TempDir()
	cacheDir := t.TempDir()
	if err := config.Save(configDir, config.Config{Greeting: "hello test"}); err != nil {
		t.Fatalf("save config: %v", err)
	}

	cmd := NewRootCommand(Options{
		Version: "test-version",
		Env: EntireEnv{
			CLIVersion:      "cli-test",
			RepoRoot:        "/tmp/repo",
			PluginConfigDir: configDir,
			PluginDataDir:   dataDir,
			PluginStateDir:  stateDir,
			PluginCacheDir:  cacheDir,
		},
	})

	out, err := execute(t, cmd)
	if err != nil {
		t.Fatalf("execute root: %v", err)
	}
	for _, want := range []string{
		"entire-brain",
		"version: test-version",
		"entire cli: cli-test",
		"repo root: /tmp/repo",
		"plugin config: " + configDir,
		"plugin data: " + dataDir,
		"plugin state: " + stateDir,
		"plugin cache: " + cacheDir,
		"greeting: hello test",
	} {
		if !strings.Contains(out, want) {
			t.Fatalf("root output missing %q:\n%s", want, out)
		}
	}
}

